+// Executes one parameter-less statement; true on success.
+bool exec(sqlite3* db, const char* sql) {
+    char* err = nullptr;
+    if (sqlite3_exec(db, sql, nullptr, nullptr, &err) != SQLITE_OK) {
+        std::cerr << "[llm_npc] sqlite: " << (err ? err : "unknown error") << "\n";
