+    CHECK(normalizeSubject("The Bakery Fire!") == "the_bakery_fire");
+    CHECK(normalizeSubject("  ray's   cab  ") == "ray_s_cab");
+    CHECK(normalizeSubject("___") == "");
+    CHECK(normalizeSubject("plaza") == "plaza");
