+    const auto good = validateProposedFacts(
+        R"([{"subject":"Bakery Fire","content":"The oven caught fire at dawn.",)"
+        R"("direction":"npc_learned"},)"
+        R"({"subject":"rays_cab","content":"Ray parks illegally.",)"
+        R"("direction":"player_learned"}])");
+    REQUIRE(good.size() == 2);
